INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_d3a1aa5976285aac98ffda', 'How to read my pass sheets', 'vincent.parker@harmonygames.co', '["brian.foster@harmonygames.co", "calvin.price@harmonygames.co", "leonard.hayes@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'How to read my pass sheets\n\nFound on: the build I first saw it on.\nTicket: the Linear key if I filed one.\nFix: the PR the dev told me it went into. Blank if nobody told me.\nRe-test: ok and a build means it is fine on that build. nr and a build means I could not make it happen on that build. again and a build means it still happens. ok, chat means I told the dev ok in our chat, the build is there. Blank means not re-tested yet.', '[{"start": 0, "end": 27, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 27, "end": 430, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '0c4ec65e52', 'f_d3a1aa5976285aac98ffda', '2025-09-26T10:24:10Z', '2025-09-26T10:31:08Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_6d0326fa006b136f1bbf82', 'ZM builds and QA passes', 'arthur.blake@harmonygames.co', '["calvin.price@harmonygames.co", "vincent.parker@harmonygames.co", "oliver.brooks@harmonygames.co", "owen.baker@harmonygames.co", "samuel.turner@harmonygames.co", "brian.foster@harmonygames.co", "leonard.hayes@harmonygames.co", "robert@harmonygames.co"]', 'private', E'ZM builds and QA passes\n\nInternal, Android and Submission are only the jobs. What matters is the branch. For ZM a QA pass only counts on a build of the main branch. A build of a feature branch is for the dev to check their own work, so a pass there has to be done again once the branch is merged.\n\nIf you want QA to look at a branch build before you merge, that is fine and it saves time, just don''t call it passed.\n\nWhich branch a build came from is in its #builds post.', '[{"start": 0, "end": 24, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 24, "end": 471, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '0bb86f7514', 'f_6d0326fa006b136f1bbf82', '2025-09-12T22:21:36Z', '2025-09-12T22:29:41Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_ea7517885d11570b54bf13', 'DD hotfix builds and QA passes', 'arthur.blake@harmonygames.co', '["calvin.price@harmonygames.co", "vincent.parker@harmonygames.co", "oliver.brooks@harmonygames.co", "owen.baker@harmonygames.co", "samuel.turner@harmonygames.co", "brian.foster@harmonygames.co", "leonard.hayes@harmonygames.co", "robert@harmonygames.co"]', 'private', E'DD hotfix builds and QA passes\n\nFor DD hotfixes a pass on the dev''s branch build is enough, we cherry-pick those straight onto the release branch.\n\nAnything that is not a hotfix goes through develop and gets its pass there.', '[{"start": 0, "end": 31, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 31, "end": 223, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '0603a1a436', 'f_ea7517885d11570b54bf13', '2025-07-10T15:43:02Z', '2025-07-10T15:49:27Z');
