-573", "", ""], ["15", "Collect & Win", "Event bar starts filling while the daily gift popup is still open", "Android #2013", "ZOM-574", "", ""], ["16", "Endless Mode", "Endless unlock banner shows again after coming back from a level", "Android #2006", "ZOM-575", "", ""], ["17", "Collect & Win", "Reward animation waits too long before the event bar fills", "iOS Internal #1750", "", "#472", "ok iOS Internal #1754"], ["18", "Collect & Win", "Event panel opens over the level-end rewards on first unlock", "iOS Internal #1750", "ZOM-576", "#472", ""], ["19", "Collect & Win", "Event progress popup opens before the level-end coins finish", "Android #2013", "ZOM-577", "", ""], ["20", "Win Streak", "Win streak freezer from the abandoned pack never shows up on the home screen", "Android #1984", "", "", ""], ["21", "Win Streak", "Streak counter jumps by two after a win when other panels are waiting", "iOS Internal #1745", "ZOM-578", "", ""], ["22", "Zombie Lane", "Zombie Lane reward animation plays under the home buttons", "iOS Internal #1727", "", "", "nr Android #2006"], ["23", "Zombie Lane", "Zombie Lane panel opens twice after claiming", "Android #1984", "", "", "ok Android #2006"], ["24", "Zombie Lane", "Lane progress bar animates from zero every time", "iOS Internal #1745", "", "", "ok Android #2010"], ["25", "Boss Arena", "Boss arena tutorial does not play when another tutorial is queued before it", "iOS Internal #1713", "", "#465", "ok, chat"], ["26", "Boss Arena", "Boss arena unlock popup shows behind the level-end rewards", "Android #1984", "", "", "nr Android #2006"], ["27", "Boss Arena", "Arena entry button can be tapped during the reward animation", "iOS Internal #1727", "", "", "nr iOS Internal #1745"], ["28", "Endless Mode", "Endless unlock banner overlaps the daily gift", "Android #1984", "ZOM-579", "", ""], ["29", "Endless Mode", "Coming back from Endless replays the home intro animation", "iOS Internal #1745", "", "", "ok iOS Internal #1750"], ["30", "Endless Mode", "Endless reward chest opens before the coins land", "Android #2006", "ZOM-580", "", ""], ["31", "Card packs", "Tap to collect prompt is missing when a pack opens after a level", "iOS Internal #1746", "", "#475", "ok iOS Internal #1757"], ["32", "Card packs", "Pack opening sound keeps playing on the home screen after the pack closes", "iOS Internal #1746", "ZOM-581", "#475", ""], ["33", "Card packs", "Last pack does not show its cards before closing", "iOS Internal #1746", "", "#475", "ok iOS Internal #1757"], ["34", "Card packs", "Pack count on the home button only updates after a restart", "Android #2006", "ZOM-582", "", ""], ["35", "Tutorials", "Tutorial hand stays on screen after the last panel closes", "iOS Internal #1727", "", "", "nr iOS Internal #1745"], ["36", "Level-end rewards", "Level-end rewards do not show at all right after an app update", "Android Submission #129", "ZOM-583", "", ""], ["37", "Win Streak", "Win streak freezer popup opens behind the season pass popup", "iOS Internal #1745", "ZOM-584", "", ""], ["38", "Season Pass", "Pass progress bar fills before the tokens arrive", "Android #1984", "", "", ""], ["", "", "", "", "", "", ""], ["Home screen flow only, the pass Brian asked me for. Everything else stays on my Bug Checklist canvas. The codes are in my pass sheet legend doc.", "", "", "", "", "", ""]]');
