INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('446ba45665ed73d2f06caca6963c6ffc', '1759264805.214409', 'D0770ET6WBW', 'message', 'EMPLOYEE_0026_SLACK_ID', 'Before Thursday''s flow review I want the queue manager to be a real epic. Right now it is one ticket, and Vincent''s flow pass is a sheet on its own. I left a note on the ticket about how I want it. One child for each area, and every report gets its line under the right child. Please also put a stock-take sheet in your ZM queue manager folder and share it with everyone on the review invite, Leonard too, and add one slide with the numbers to your queue manager deck. When it is done tell me here how many reports are passed, how many wait on QA, how many wait on a fix, how many areas are clear and how many reports are on the review list.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T20:40:05.214409Z', '{}');
