VALUES ('ZOM-567', NULL, 'team_ZOM', NULL, 'usr_bdf01b53c6a92c5e', 'usr_65c76e0b87aa7e9b', 'Todo', NULL, 'ZOM-567', 567, 'Win streak tutorial at level 20 freezes the home screen', E'At level 20 the win streak tutorial starts and the home screen stops taking taps. I have to kill the app.\n\nSeen on Android 1974.', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Bug"]', '[]', '[]', '[]', false, '2025-09-30T16:43:18Z', '2025-09-30T17:41:30Z');
