VALUES ('ZOM-568', NULL, 'team_ZOM', NULL, 'usr_49b9dfa5208d400d', 'usr_65c76e0b87aa7e9b', 'Todo', NULL, 'ZOM-568', 568, 'Level-end coins fly while the pre-level panel is already open', E'If I tap play right after a level, the pre-level panel is open and the level-end coins are still flying over it.\n\nSeen on Android 1974.', 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Bug"]', '[]', '[]', '[]', false, '2025-09-30T16:49:52Z', '2025-09-30T16:52:21Z');
