INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence)
VALUES ('comment_faaa792418a942cd40be046d8d217a7d', 'ZOM-543', 'usr_fc22d5941b2aeb5c', NULL, E'How I want this epic.\n\nChildren: Tutorials, Level-end rewards, Daily Gift, Season Pass, Collect & Win, Win Streak, Zombie Lane, Boss Arena, Endless Mode, Card packs. One child each, same team, no assignee.\n\nReports: the rows of Vincent''s flow pass sheet, all of them. For Vincent that sheet is the list, so don''t add things from his chats, and his Bug Checklist canvas and the Collect & Win canvas stay as they are. Plus any bug somebody else on the team saw in a build and told you about in a DM since Vincent started his pass on the 26th, about the home screen after a level. If it is already a row, don''t count it twice. The skip tutorial exceptions Oliver has in #zombie-bugs and the input blocker I parked are not on the sheet and stay off.\n\nStatus of a report, one of three. Passed: Vincent''s ok or nr on a build that counts under Arthur''s rule for QA passes, and it stays passed unless somebody says later, on a build made after that one, that it is back. Waiting on QA: not passed, and the fix is merged. Vincent''s Fix column is only what he was told at the time, so check the PR: it has to be merged, and if the review on it says a fix is not in there, it is not. A row with no PR in the sheet counts as merged too if the dev wrote on a merged PR of theirs that it has the fix. Waiting on a fix: everything else, also when it came back after a pass.\n\nLine under the child: if a ticket already has the report, move that ticket under the child and leave a note with the status and why. If its state does not match the status, put Done for Passed, In Validation for Waiting on QA, Todo for Waiting on a fix. If no ticket has it, make a sub-issue under the child with the report as the title and the state the same way. Vincent sometimes writes a row for something that already has a ticket under another name, use that ticket then. No priority and no assignee on the new ones, that is Julia''s point about your tickets, I will set them.\n\nA child is Clear when all its reports are Passed, otherwise Open. Set the child to Done if it is Clear and to Todo if it is Open.\n\nReview list: a report that is not Passed, in an area Leonard''s review card lists.\n\nSheet: tab Reports with Report, Area, Status, Ticket, Review list, Why. Tab Areas with Area, Status, Open reports. Slide: the five numbers I asked you for.', false, '2025-09-30T20:25:37Z', '2025-09-30T20:25:37Z', 1);
